import"./chunk-2NFLSA4Y.js";var o={workPower:{theory:{concept:"[[Mechanical work is done when a force moves a body; it equals the force times the displacement times the cosine of the angle between them: W = F \xB7 s \xB7 cos \u03B1.]] Power is the work done per unit time, P = W / t, measured in watts (1 W = 1 J/s): a crane and a person can do the same work lifting a load, but the crane does it faster and so has a greater power."},section:{work:{title:"What is work?",text:"[[Work is force multiplied by the distance moved in the direction of the force: W = F \xB7 s.]] It is measured in joules: 1 J is the work of a 1 N force over 1 m. Lifting a 1 kg bag by 1 m takes about 10 J; lifting a 50 kg load to the third floor (10 m) about 5 000 J."},angle:{title:"Pulling at an angle",text:"Only the part of the force along the motion does work: W = F \xB7 s \xB7 cos \u03B1. Pull a sled with a rope at 60\xB0 and only half of your force moves it forwards; the rest lifts the sled a little. A force at right angles to the motion does no work at all \u2014 like the weight of a crate sliding along a floor."},noWork:{title:"Effort without work",text:"[[If nothing moves, no work is done, however hard you push.]] Pushing a wall, or pulling a crate that friction holds in place, makes your muscles tired, but the work in the physics sense is zero: s = 0."},friction:{title:"Where the work goes",text:"The work of the pull is shared out. Friction does negative work: it takes energy away and turns it into heat. What is left becomes kinetic energy: W_pull + W_friction = \xBD\xB7m\xB7v\xB2 (the work\u2013energy theorem). The energy bars show this balance at every moment."},power:{title:"Power: how fast",text:"A person can keep up about 100 W for a long time and several hundred watts for a short sprint up the stairs; a kettle uses 2 000 W, a small crane tens of kilowatts. [[When a force moves something at speed v, its power is P = F \xB7 v.]]"},units:{title:"Horsepower",text:"James Watt wanted to sell steam engines to mine owners who used horses, so he measured what a horse could do. One horsepower is about 746 W \u2014 enough to lift 75 kg by 1 m every second. The unit watt is named after him."},check:{title:"Check your understanding",text:"How much work does it take to lift 20 kg by 2 m? (About 400 J.) Does holding it still do work? (No.) Two people climb the same stairs, one in 10 s and one in 20 s: who did more work, and who had more power? (The same work; the faster one twice the power.) Try each answer in the simulation."}},formula:{work:"Work of a force along the motion",power:"Power: work divided by the time it took",lift:"Work to lift a mass m to a height h",angle:"Work of a force at angle \u03B1 to the motion",energy:"Work\u2013energy theorem: the total work becomes kinetic energy",instant:"Power of a force moving at speed v"},variable:{work:"Work",power:"Power"},assumption:{constant:"The pulling force and its direction stay constant; the crate slides without tipping.",friction:"Friction is the same when starting and when sliding (one coefficient \u03BC).",lift:"The lifters start at full speed and stop exactly at the top; rope and pulley are ideal."},param:{mode:"Experiment",force:"Pulling force",angle:"Rope angle",distance:"Distance to pull",power:"Lifter power",height:"Lifting height",mass:"Mass",friction:"Friction coefficient \u03BC",compare:"Second lifter",power2:"Power of lifter 2"},hint:{angle:"0\xB0 pulls horizontally; a steeper rope also lifts the crate a little.",power:"A person about 100 W, a horse 746 W (1 horsepower).",friction:"Ice is slippery (0.05), rubber grips (0.8)."},preset:{pull:"Pulling a crate",lift:"Lifting a load",person:"Person",horse:"Horse",motor:"Motor",crane:"Crane",ice:"Ice",wood:"Wood",rubber:"Rubber"},measure:{distance:"Distance moved",workForce:"Work of the pull",workFriction:"Work of friction",power:"Power of the pull now",averagePower:"Average power",normalForce:"Normal force",frictionForce:"Friction force",height:"Height",work:"Work done",liftTime:"Time to the top",liftSpeed:"Lifting speed",liftTime2:"Time to the top (lifter 2)",work2:"Work done (lifter 2)"},view:{finish:"Finish",workForce:"Work of the pull",pulling:"Work so far {work} \xB7 power now {power}",stuck:"Friction holds the crate: it does not move, so no work is done",lifting:"The same work {work} for any lifter \u2014 this one needs {time}",race:"Same work {work}: lifter 1 needs {t1}, lifter 2 {t2}",allForcesOption:"Weight and normal force",barsOption:"Work and energy bars",split:"Heat (friction) + kinetic"},graph:{energy:"Work and energy against distance",workTime:"Work against time (the slope is the power)"},challenge:{noWork:{title:"Hard work, no work",description:"Pull with at least 100 N without moving the crate. How much work did you do?",hint:"Make the friction strong or the pull weak \u2014 or pull steeply upwards."},kilojoule:{title:"One kilojoule",description:"Do exactly 1 000 J of work by pulling the crate to the finish.",hint:"W = F \xB7 s \xB7 cos \u03B1. With a horizontal rope and 10 m, you need 100 N."},horse:{title:"Watt's horse",description:"Lift 75 kg with one horsepower (746 W). How fast does it rise?",hint:"Choose the horse preset and set the mass to 75 kg."},race:{title:"Same work, different power",description:"Race two lifters, one at least four times as powerful as the other, to the top.",hint:"They do the same work; the more powerful one needs a quarter of the time."},bestAngle:{title:"The best angle",description:"With friction, find the rope angle that pulls the crate fastest: tan \u03B1 = \u03BC.",hint:"Pulling a little upwards lightens the crate and reduces friction \u2014 but too steep wastes force."},crane:{title:"Crane operator",description:"Lift 1 000 kg by 30 m in 30 s or less.",hint:"P = m\xB7g\xB7h / t. You need about 10 kW."}}}},r={sim:o};export{r as default,o as sim};
